const assert = require('assert');
const NoteStore = require('./notes');

const store = new NoteStore();

// test add
const n1 = store.add('buy milk');
assert.strictEqual(n1.id, 1);
assert.strictEqual(n1.text, 'buy milk');
assert.strictEqual(n1.archived, false);

const n2 = store.add('write tests');
assert.strictEqual(n2.id, 2);

// test list
assert.strictEqual(store.list().length, 2);

// test archive
assert.strictEqual(store.archive(1), true);
assert.strictEqual(store.list().find(n => n.id === 1).archived, true);
assert.strictEqual(store.archive(999), false);

// test listArchived
assert.strictEqual(store.listArchived().length, 1);
assert.strictEqual(store.listArchived()[0].id, 1);

// test remove
assert.strictEqual(store.remove(1), true);
assert.strictEqual(store.list().length, 1);
assert.strictEqual(store.remove(999), false);

console.log('All tests passed!');
